using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Reflection;
class ToxicWoodlandUiChecks {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static object Get(Game g,string n){return typeof(Game).GetField(n,F).GetValue(g);}static void Set(Game g,string n,object v){typeof(Game).GetField(n,F).SetValue(g,v);}static object Call(Game g,string n,params object[] a){return typeof(Game).GetMethod(n,F).Invoke(g,a);}static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Pump(int ms=350){var watch=System.Diagnostics.Stopwatch.StartNew();while(watch.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(8);}}
 static void Shot(Control c,string name){using(var img=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(img,c.ClientRectangle);img.Save("D:/WORK/Cet6Story/.validation/"+name+".png");Check(img.GetPixel(4,4).ToArgb()!=Color.Black.ToArgb(),"no black corner");}}
 [STAThread]static void Main(){try{Application.EnableVisualStyles();using(var game=new Game()){game.Opacity=0;game.Show();Pump();var save=new Save();Set(game,"save",save);Call(game,"ShowToxicWoodlandEntry");Check((bool)Get(game,"woodlandChanging"),"transition covers rebuild");Check(game.Controls.OfType<WoodlandCrossfade>().Count()==1,"single overlay");Pump();Check(!(bool)Get(game,"woodlandChanging")&&game.Controls.OfType<WoodlandCrossfade>().Count()==0,"transition cleanup");save.toxicWoodland=ToxicWoodland.Create(5,save);Call(game,"ShowToxicWoodland");Call(game,"StopAudio");Pump();var map=(WoodlandRouteMap)Get(game,"woodlandMap");Check(map.Art!=null&&map.Run.nodes.Count>10,"terrain and branching nodes");for(int i=0;i<12;i++){Call(game,"ShowToxicWoodland");Check(Object.ReferenceEquals(map,Get(game,"woodlandMap")),"map reused");}game.Size=new Size(1400,900);Pump();Shot(map,"toxic-woodland-route-ui");game.Size=new Size(800,500);Pump();Shot(map,"toxic-woodland-route-small");game.Size=new Size(1280,800);Pump();
 var r=save.toxicWoodland;var chosen=ToxicWoodland.Available(r).First();ToxicWoodland.Choose(r,chosen.id);Call(game,"ShowToxicWoodland");Shot(map,"toxic-woodland-road-choice");ToxicWoodland.ResolveRoad(r,false);Call(game,"ToxicTransition",new Action(()=>Call(game,"ShowToxicWoodland")));Pump();Check(!(bool)Get(game,"woodlandChanging"),"travel fade finishes");
 r.current=r.nodes.First(n=>n.kind=="boss").id;r.steps=10;r.mode="node-combat";r.combat=null;Call(game,"ToxicTransition",new Action(()=>Call(game,"ShowToxicWoodland")));Pump();Call(game,"StopAudio");var canvas=(PartyBattleCanvas)Get(game,"partyCanvas");Check(canvas.Scene!=null&&PartyMonsterArt.Get("D:/WORK/Cet6Story","boss",null)!=null,"boss and forest art");Shot(canvas,"toxic-woodland-boss-ui");var b=r.combat.partyBattle;var h=b.heroes.First(u=>u.id==b.active);var s=HeroSkills.For(h.id).First(x=>x.Damage>0&&PartyCombat.CanUse(b,h,x));Check(PartyCombat.BeginSkill(b,b.selectedHero,s.Id,PartyCombat.Targets(b,h,s)[0].id),"cast");Call(game,"NextPartyQuestion",r.combat);Call(game,"RenderPartyBattle",r.combat);Pump(30);Check(Object.ReferenceEquals(canvas,Get(game,"partyCanvas")),"quiz stable canvas");Call(game,"AnswerPartyQuestion",r.combat.question.answer);Pump(30);Check(Object.ReferenceEquals(canvas,Get(game,"partyCanvas")),"answer stable canvas");var json=Engine.Json.Serialize(save);save=Engine.Json.Deserialize<Save>(json);Set(game,"save",save);Call(game,"ShowMain");Call(game,"ContinueGame");Pump();Check((string)Get(game,"page")=="tavern-hub","continue returns to hub");Check(save.toxicWoodland.combat.partyBattle.phase=="feedback","hub preserves pending battle");Call(game,"ShowToxicWoodlandEntry");Pump();Check((string)Get(game,"page")=="toxic-entry","expedition resume prompt");var content=(Control)Get(game,"content");var surface=content.Controls[0];var panel=surface.Controls[0];Check(panel.Controls.OfType<OutlinedLabel>().Any(l=>l.Text.Contains("上次未结束")),"resume explanation");var resume=panel.Controls.OfType<VNButton>().Single(x=>x.Text=="继续上次未完成的远征");var back=panel.Controls.OfType<VNButton>().Single(x=>x.Text=="返回驿站");Check(panel.Controls.OfType<VNButton>().Count()==2,"only two resume buttons");Check(resume.Left==(panel.Width-resume.Width)/2&&back.Left==resume.Left&&back.Top>resume.Bottom,"centered vertical layout");Shot(panel,"toxic-resume-two-buttons");resume.PerformClick();Check(Get(game,"menuLoading")!=null,"resume loading animation");Pump(1600);Check(Get(game,"menuLoading")==null,"resume loading finishes");Check((string)Get(game,"page")=="toxic-battle","explicit resume restores battle");Check(save.toxicWoodland.combat.partyBattle.phase=="feedback","resume pending feedback");game.Close();Console.WriteLine("PASS UI: entry, 12 stable redraws, normal/minimum resize, road and boss art, crossfade cleanup, quiz canvas reuse, continue save restore");}}catch(Exception ex){while(ex!=null){Console.WriteLine(ex.GetType().Name+": "+ex.Message);ex=ex.InnerException;}Environment.ExitCode=1;}}
}
